def machine_fingerprint_set():
    """Conjunto de códigos que representam ESTA máquina (o principal + cada
    componente de hardware sozinho). Enviar todos para a Central permite que
    ela reconheça a máquina mesmo se a leitura de um componente oscilar —
    é a MESMA tolerância que a licença offline já usa. Retorna lista de str.
    Nunca lança exceção."""
    fps = set()
    try:
        principal = machine_fingerprint()
        if principal:
            fps.add(principal)
    except Exception:
        pass
    # tenta o conjunto tolerante do núcleo (uuid sozinho, board sozinho, etc.)
    try:
        if _CORE_OK and hasattr(_core, "_fingerprint_set"):
            for f in _core._fingerprint_set():
                if f:
                    fps.add(f)
    except Exception:
        pass
    return sorted(fps)


# Estado global da licença (checado no startup)
LICENSE_STATE = {"ok": False, "fingerprint": "", "reason": "sem_licenca"}


def refresh_license():
    global LICENSE_STATE
    LICENSE_STATE = check_license()
    return LICENSE_STATE


# ═══════════════════════════════════════════════════════════════════
#  CENTRAL DE LICENÇAS (verificação online)
#  Além da licença offline (núcleo), o sistema consulta a Central para
#  saber se o cliente continua ativo. Regras:
#   - Central diz "inativo"  → BLOQUEIA
#   - Central diz "ativo"    → libera (e guarda o horário como "último ok")
#   - Central inacessível    → NÃO bloqueia (internet caiu não é motivo).
#     Só bloqueia por falta de resposta se ficar MUITOS dias sem NENHUM
#     contato bem-sucedido (proteção contra cliente que corta a internet
#     de propósito para sempre). Esse limite é largo e tolerante.
# ═══════════════════════════════════════════════════════════════════
import hmac as _hmac_mod
import hashlib as _hashlib_mod

CENTRAL_CONFIG_PATH = Path(__file__).with_name("central_config.json")
# Estado da verificação online (memória + persistido)
CENTRAL_STATE = {"liberado": True, "motivo": "sem_verificacao", "ultimo_ok": None,
                 "verificado_em": None}
# Dias que o sistema tolera SEM nenhuma resposta positiva da Central antes de,
# por precaução, pedir reconexão. Largo de propósito (não pune queda de internet).
CENTRAL_MAX_DIAS_OFFLINE = 14


def _central_config():
    """Lê a config da Central: {url, licenca_id, secret}."""
    try:
        if CENTRAL_CONFIG_PATH.exists():
            return json.loads(CENTRAL_CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {}


def _ja_ativado_alguma_vez():
    """True se este sistema já foi ativado pela Central em algum momento
    (existe um licenca_id salvo no central_config). Uma vez ativado, o sistema
    NÃO deve voltar para a tela de ativação por conta de oscilação do código da
    máquina — quem controla bloqueio a partir daí é a Central (tela 'suspenso').
    Isso evita pedir a licença de novo sem motivo."""
    try:
        cfg = _central_config()
        return bool(cfg.get("url") and cfg.get("licenca_id"))
    except Exception:
        return False


def _central_salvar_estado():
    try:
        CENTRAL_CONFIG_PATH  # noqa
        estado_path = Path(__file__).with_name("central_estado.json")
        estado_path.write_text(json.dumps(CENTRAL_STATE), encoding="utf-8")
    except Exception:
        pass


def _central_carregar_estado():
    global CENTRAL_STATE
    try:
        estado_path = Path(__file__).with_name("central_estado.json")
        if estado_path.exists():
            CENTRAL_STATE.update(json.loads(estado_path.read_text(encoding="utf-8")))
    except Exception:
        pass


def verificar_central():
    """Consulta a Central de Licenças. Atualiza CENTRAL_STATE.
    Retorna True se pode funcionar, False se a Central mandou bloquear."""
    cfg = _central_config()
    url = cfg.get("url", "").rstrip("/")
    licenca_id = cfg.get("licenca_id", "")
    secret = cfg.get("secret", "")

    # Se a Central não está configurada, não bloqueia (modo offline puro).
    if not url or not licenca_id:
        CENTRAL_STATE["liberado"] = True
        CENTRAL_STATE["motivo"] = "central_nao_configurada"
        return True

    fp = ""
    try:
        fp = machine_fingerprint()
    except Exception:
        pass

    try:
        import requests as _rq
        r = _rq.post(f"{url}/api/verificar",
                     json={"licenca_id": licenca_id, "fingerprint": fp,
                           "fingerprints": machine_fingerprint_set()},
                     timeout=8)
        if r.status_code == 200:
            d = r.json()
            # valida o ticket (assinatura HMAC) para garantir que a resposta
            # veio mesmo da Central, e não de um impostor/DNS sequestrado.
            if secret:
                recebido = d.get("ticket", "")
                corpo = {k: d[k] for k in ("liberado", "motivo", "ts") if k in d}
                calc = _hmac_mod.new(secret.encode(),
                                     json.dumps(corpo, sort_keys=True,
                                                separators=(",", ":")).encode(),
                                     _hashlib_mod.sha256).hexdigest()
                if not _hmac_mod.compare_digest(calc, recebido):
                    # resposta não confiável → por segurança, não bloqueia,
                    # mas também não registra como "ok" (trata como offline)
                    CENTRAL_STATE["motivo"] = "resposta_nao_confiavel"
                    return _central_avaliar_offline()

            liberado = bool(d.get("liberado"))
            CENTRAL_STATE["liberado"] = liberado
            CENTRAL_STATE["motivo"] = d.get("motivo", "")
            CENTRAL_STATE["verificado_em"] = datetime.now(timezone.utc).isoformat()
            if liberado:
                CENTRAL_STATE["ultimo_ok"] = datetime.now(timezone.utc).isoformat()
            _central_salvar_estado()
            return liberado
        else:
            # erro no servidor → trata como offline (não pune o cliente)
            return _central_avaliar_offline()
    except Exception:
        # sem internet / central fora do ar → NÃO bloqueia
        return _central_avaliar_offline()


def _central_avaliar_offline():
    """Quando não conseguiu falar com a Central: decide sem puni-lo por queda
    de internet, mas com um limite largo contra abuso permanente."""
    ultimo = CENTRAL_STATE.get("ultimo_ok")
    if not ultimo:
        # nunca conseguiu falar com a Central ainda → dá o benefício da dúvida
        CENTRAL_STATE["liberado"] = True
        CENTRAL_STATE["motivo"] = "central_inacessivel_sem_historico"
        return True
    try:
        d = datetime.fromisoformat(ultimo)
        dias = (datetime.now(timezone.utc) - d).days
    except Exception:
        dias = 0
    if dias > CENTRAL_MAX_DIAS_OFFLINE:
        # muito tempo sem NENHUM contato bem-sucedido → pede reconexão
        CENTRAL_STATE["liberado"] = False
        CENTRAL_STATE["motivo"] = f"sem_contato_ha_{dias}_dias"
        return False
    # dentro do período tolerado → continua funcionando
    CENTRAL_STATE["liberado"] = True
    CENTRAL_STATE["motivo"] = f"offline_tolerado_{dias}_dias"
    return True


