# Servidor web
# ---------------------------------------------------------------------------
app = FastAPI()


@app.on_event("startup")
async def _startup():
    broadcaster.loop = asyncio.get_event_loop()
    # Central de Licenças: carrega o último estado e verifica em segundo plano.
    _central_carregar_estado()

    def _loop_central():
        # verifica logo ao subir e depois a cada 3 horas
        while True:
            try:
                verificar_central()
            except Exception as exc:
                print("[central] erro ao verificar:", exc)
            time.sleep(3 * 3600)  # 3 horas

    threading.Thread(target=_loop_central, daemon=True, name="central").start()

    # se o acesso remoto estiver marcado como "sempre ligado", sobe o túnel
    try:
        cfg = _remoto_cfg()
        if cfg.get("auto") and cfg.get("token"):
            asyncio.get_event_loop().run_in_executor(None, _tunnel_start, 8000)
            print("[remoto] acesso remoto automático ativado no início.")
    except Exception as exc:
        print("[remoto] não consegui iniciar o acesso remoto automático:", exc)


