def _flashforge_scan(timeout=6):
    """Procura impressoras Flashforge na rede via broadcast UDP.
    A Flashforge responde a um broadcast na porta 19000/48899 com seus dados.
    Retorna lista de {ip, serial, nome, modelo}."""
    import socket
    achadas = {}
    # A Flashforge (5M/AD5X) responde a um broadcast de descoberta.
    # Tentamos as portas conhecidas de descoberta.
    portas_descoberta = [19000, 48899]
    mensagem = b"\xc0\xa8\x00\xde\x46\x50\x00\x00"  # padrão de descoberta FF

    for porta in portas_descoberta:
        sock = None
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
            sock.settimeout(1.0)
            try:
                sock.sendto(mensagem, ("255.255.255.255", porta))
            except Exception:
                pass
            fim = time.time() + (timeout / len(portas_descoberta))
            while time.time() < fim:
                try:
                    dados, origem = sock.recvfrom(4096)
                except socket.timeout:
                    continue
                except Exception:
                    break
                ip = origem[0]
                if ip in achadas:
                    continue
                # tenta extrair nome/série da resposta (texto legível)
                try:
                    txt = dados.decode("utf-8", "ignore")
                except Exception:
                    txt = ""
                nome = ""
                for linha in txt.replace("\x00", "\n").split("\n"):
                    linha = linha.strip()
                    if linha and len(linha) > 2 and not linha.startswith("\\"):
                        nome = linha
                        break
                achadas[ip] = {"ip": ip, "serial": "", "nome": nome or "Flashforge",
                               "modelo": "AD5X"}
        except Exception:
            pass
        finally:
            if sock:
                try: sock.close()
                except Exception: pass

    # Para cada IP achado, tenta pegar o número de série pelo /detail
    # (sem check code, alguns firmwares respondem info básica; se não, fica vazio)
    for ip, info in achadas.items():
        try:
            d = _flashforge_detail(ip, "", "", timeout=3)
            if d:
                dd = d.get("detail", d)
                info["serial"] = dd.get("serialNumber", "") or info["serial"]
                info["modelo"] = dd.get("machineType", "") or info["modelo"]
        except Exception:
            pass

    return list(achadas.values())


@app.get("/api/flashforge/raw")
async def api_flashforge_raw(request: Request):
    """Diagnóstico: mostra os dados brutos que a Flashforge está enviando,
    E o número de série / código que estão sendo usados (para achar o erro)."""
    if (block := _need_auth(request)):
        return block
    resultado = {}
    with CFG_LOCK:
        cfgs = [dict(c) for c in PRINTERS_CFG if c.get("brand") == "flashforge"]
    with STATE_LOCK:
        for name, st in STATE.items():
            meta = st.get("_meta", {})
            if meta.get("brand") == "flashforge":
                cfg = next((c for c in cfgs if c["name"] == name), {})
                serial = cfg.get("serial", "")
                code = cfg.get("check_code", "")
                resultado[name] = {
                    "_config_enviada": {
                        "ip": cfg.get("ip", ""),
                        "serial_completo": serial,
                        "serial_tamanho": len(serial),
                        "serial_comeca_com_SN": serial.upper().startswith("SN"),
                        "check_code_tamanho": len(code),
                    },
                    "resposta_da_impressora": meta.get("_raw", "sem dados ainda"),
                }
    if not resultado:
        return {"aviso": "Nenhuma impressora Flashforge cadastrada. "
                         "Confira se ela esta adicionada."}
    return resultado


@app.post("/api/flashforge/testar_seriais")
async def api_flashforge_testar_seriais(request: Request):
    """Testa vários formatos do número de série para descobrir qual a
    impressora aceita. Recebe {ip, check_code, serial} e testa variações."""
    if (block := _need_auth(request)):
        return block
    b = await request.json()
    ip = (b.get("ip") or "").strip()
    code = (b.get("check_code") or "").strip()
    serial = (b.get("serial") or "").strip()
    if not ip or not code:
        return {"ok": False, "error": "Informe o IP e o código."}

    # gera variações do serial para testar
    base = serial.upper()
    sem_sn = base[2:] if base.startswith("SN") else base
    variacoes = []
    vistos = set()
    for cand in [serial, base, sem_sn, "SN" + sem_sn,
                 serial.lower(), sem_sn.lower()]:
        if cand and cand not in vistos:
            vistos.add(cand)
            variacoes.append(cand)

    resultados = []
    for cand in variacoes:
        detail = await asyncio.to_thread(_flashforge_detail, ip, cand, code)
        d = detail.get("detail", detail) if isinstance(detail, dict) else {}
        recusou = isinstance(d, dict) and "sn" in str(d.get("message", "")).lower()
        funcionou = isinstance(d, dict) and not recusou and (
            d.get("status") or d.get("machineStatus") or d.get("printProgress") is not None
            or "detail" in (detail or {}))
        resultados.append({
            "serial_testado": cand,
            "funcionou": bool(funcionou),
            "resposta": d if isinstance(d, dict) else str(detail),
        })
        if funcionou:
            break

    return {"ok": True, "resultados": resultados}


