@app.post("/api/flashforge/corrigir_serial")
async def api_flashforge_corrigir_serial(request: Request):
    """Corrige o número de série de uma Flashforge já cadastrada, sem precisar
    remover e adicionar de novo. Testa o SN antes de salvar."""
    if (block := _need_auth(request)):
        return block
    b = await request.json()
    nome = (b.get("nome") or "").strip()
    novo_serial = (b.get("serial") or "").strip()
    if not nome or not novo_serial:
        return {"ok": False, "error": "Informe o nome da impressora e o número de série."}

    # acha a config da impressora
    with CFG_LOCK:
        cfg = next((c for c in PRINTERS_CFG if c["name"] == nome
                    and c.get("brand") == "flashforge"), None)
    if not cfg:
        return {"ok": False, "error": "Impressora Flashforge não encontrada."}

    ip = cfg.get("ip", "")
    code = cfg.get("check_code", "")

    # testa o novo serial ANTES de salvar
    detail = await asyncio.to_thread(_flashforge_detail, ip, novo_serial, code)
    if detail is None:
        return {"ok": False, "error": "Não consegui falar com a impressora. Confira o IP e o Modo LAN."}
    d = detail.get("detail", detail)
    # se a impressora reclamar do SN, avisa
    if isinstance(d, dict) and d.get("message") and "sn" in str(d.get("message", "")).lower():
        return {"ok": False, "error": f"A impressora recusou este número de série: \"{d.get('message')}\". "
                "Confira se digitou completo, com o SN na frente."}
    if isinstance(d, dict) and d.get("code") not in (0, None) and d.get("message"):
        return {"ok": False, "error": f"A impressora respondeu: {d.get('message')}"}

    # deu certo → para a impressora, atualiza o serial, salva e reinicia
    handle = PRINTERS.get(nome)
    if handle and handle.get("stop"):
        handle["stop"].set()
    with CFG_LOCK:
        cfg["serial"] = novo_serial
        save_printers(PRINTERS_CFG)
    await asyncio.to_thread(start_printer, cfg)
    return {"ok": True, "info": "Número de série corrigido! As métricas devem aparecer em instantes."}


